exercises.solution:
def cache_put(cache, name, ip, ttl, now):
    cache[name] = (ip, now + ttl)


def cache_get(cache, name, now):
    if name not in cache:
        return None
    ip, expires_at = cache[name]
    if now >= expires_at:
        del cache[name]
        return None
    return ip


def resolve(cache, name, now, authoritative, ttl=300):
    ip = cache_get(cache, name, now)
    if ip is not None:
        return ip
    ip = authoritative[name]
    cache_put(cache, name, ip, ttl, now)
    return ip

tests.code:
auth = {"www.stubwhistle.example": "198.51.100.20"}
c = {}
assert resolve(c, "www.stubwhistle.example", 0, auth) == "198.51.100.20"
auth["www.stubwhistle.example"] = "198.51.100.99"
assert resolve(c, "www.stubwhistle.example", 100, auth) == "198.51.100.20"
assert resolve(c, "www.stubwhistle.example", 300, auth) == "198.51.100.99"

