IDEMPOTENT = {"GET", "PUT", "DELETE"}
RETRYABLE = {429, 503}


def should_retry(method, status):
    """Retry only temporary failures (429, 503) for idempotent methods."""
    if method in IDEMPOTENT and status in RETRYABLE:
        return True
    return False

